  1	using System.IO;
  2	using LoadOrderKeeper.Models;
  3	
  4	namespace LoadOrderKeeper.Services
  5	{
  6	    public static class DiffService
  7	    {
  8	        private static readonly ViewTexts.LocalizationService _localization = ViewTexts.LocalizationService.Instance;
  9	
 10	        public static async Task<IReadOnlyList<DiffLineModel>> GetPluginsDiffAsync(AppConfigModel config)
 11	        {
 12	            if (config is null)
 13	            {
 14	                throw new ArgumentNullException(nameof(config));
 15	            }
 16	
 17	            if (!config.IsValid())
 18	            {
 19	                throw new InvalidOperationException("Configuration paths are invalid.");
 20	            }
 21	
 22	            string targetPath = config.GetPluginsFilePath();
 23	            string referencePath = config.GetReferenceFilePath();
 24	
 25	            if (!File.Exists(referencePath))
 26	            {
 27	                throw new FileNotFoundException("Reference file not found.", referencePath);
 28	            }
 29	
 30	            if (!File.Exists(targetPath))
 31	            {
 32	                throw new FileNotFoundException("Plugins file not found.", targetPath);
 33	            }
 34	
 35	            var referenceMods = await FileService.ReadModListAsync(referencePath, isReferenceFile: true).ConfigureAwait(false);
 36	            var currentMods   = await FileService.ReadModListAsync(targetPath).ConfigureAwait(false);
 37	
 38	            var refFileNames = referenceMods.Select(m => m.FileName).ToList();
 39	            var curFileNames = currentMods.Select(m => m.FileName).ToList();
 40	
 41	            var lcs = ComputeLcs(refFileNames, curFileNames, StringComparer.OrdinalIgnoreCase);
 42	
 43	            return ClassifyChanges(referenceMods, currentMods, lcs);
 44	        }
 45	
 46	        /// <summary>
 47	        /// Checks if there are any moved mods that are NOT part of dependent change lists.
 48	        /// These independent moves indicate external reordering that sorting could fix.
 49	        /// </summary>
 50	        public static async Task<bool> HasIndependentMovedModsAsync(AppConfigModel config)
 51	        {
 52	            if (config is null)
 53	            {
 54	                throw new ArgumentNullException(nameof(config));
 55	            }
 56	
 57	            if (!config.IsValid())
 58	            {
 59	                return false;
 60	            }
 61	
 62	            string targetPath = config.GetPluginsFilePath();
 63	            string referencePath = config.GetReferenceFilePath();
 64	
 65	            if (!File.Exists(referencePath) || !File.Exists(targetPath))
 66	            {
 67	                return false;
 68	            }
 69	
 70	            var diffLines = await GetPluginsDiffAsync(config).ConfigureAwait(false);
 71	            
 72	            // Get all mods that are part of dependent change lists
 73	            var dependentMods = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
 74	            foreach (var line in diffLines)
 75	            {
 76	                foreach (var dependent in line.DependentChanges)
 77	                {
 78	                    dependentMods.Add(dependent.FileName);
 79	                }
 80	            }
 81	            
 82	            // Check if there are any moved mods that are NOT in the dependent set
 83	            bool hasIndependentMoves = diffLines.Any(line => 
 84	                line.ChangeType == DiffChangeType.Moved && 
 85	                !dependentMods.Contains(line.FileName));
 86	            
 87	            return hasIndependentMoves;
 88	        }
 89	
 90	        /// <summary>
 91	        /// Computes the Longest Common Subsequence of two string lists using a standard
 92	        /// dynamic-programming approach. Returns a list of paired (refIndex, curIndex) tuples
 93	        /// representing the LCS in order, where refIndex is the position in
 94	        /// <paramref name="reference"/> and curIndex is the position in <paramref name="current"/>.
 95	        /// </summary>
 96	        internal static List<(int refIndex, int curIndex)> ComputeLcs(
 97	            IReadOnlyList<string> reference,
 98	            IReadOnlyList<string> current,
 99	            StringComparer comparer)
100	        {

101	            int m = reference.Count;
102	            int n = current.Count;
103	
104	            // Build DP table
105	            var dp = new int[m + 1, n + 1];
106	            for (int i = 1; i <= m; i++)
107	            {
108	                for (int j = 1; j <= n; j++)
109	                {
110	                    if (comparer.Equals(reference[i - 1], current[j - 1]))
111	                    {
112	                        dp[i, j] = dp[i - 1, j - 1] + 1;
113	                    }
114	                    else
115	                    {
116	                        dp[i, j] = Math.Max(dp[i - 1, j], dp[i, j - 1]);
117	                    }
118	                }
119	            }
120	
121	            // Backtrack to recover the LCS pairs
122	            var result = new List<(int refIndex, int curIndex)>(dp[m, n]);
123	            int ri = m, ci = n;
124	            while (ri > 0 && ci > 0)
125	            {
126	                if (comparer.Equals(reference[ri - 1], current[ci - 1]))
127	                {
128	                    result.Add((ri - 1, ci - 1));
129	                    ri--;
130	                    ci--;
131	                }
132	                else if (dp[ri - 1, ci] >= dp[ri, ci - 1])
133	                {
134	                    ri--;
135	                }
136	                else
137	                {
138	                    ci--;
139	                }
140	            }
141	
142	            result.Reverse();
143	            return result;
144	        }
145	
146	        /// <summary>
147	        /// Classifies changes between <paramref name="reference"/> and <paramref name="current"/>
148	        /// mod lists given the pre-computed LCS alignment. Returns a flat list of
149	        /// <see cref="DiffLineModel"/> entries (dependents are nested under their causal change).
150	        /// </summary>
151	        /// <remarks>
152	        /// Classification pipeline:
153	        /// <list type="number">
154	        ///   <item>Build fast lookup sets: partition reference and current items into LCS members
155	        ///         (unchanged), removed candidates (reference only), and new candidates (current only).</item>
156	        ///   <item>Identify shifted LCS items: LCS members whose absolute positions differ between
157	        ///         the two lists → candidate dependent changes (Moved).</item>
158	        ///   <item>Same-filename reconciliation: removed mod whose filename also appears in the new
159	        ///         set → Moved (swapped); performed before replacement detection.</item>
160	        ///   <item>Replacement detection: removed item at reference position R paired with the new
161	        ///         item at the corresponding LCS-aligned current position → Replaced.</item>
162	        ///   <item>Remaining new items classified as Added (beyond all surviving reference mods)
163	        ///         or Inserted (within the range of surviving reference mods).</item>
164	        ///   <item>Shifted LCS items grouped as dependent changes under their causal
165	        ///         insertion/deletion and removed from the top-level list.</item>
166	        /// </list>
167	        /// </remarks>
168	        internal static List<DiffLineModel> ClassifyChanges(
169	            IReadOnlyList<ModEntryModel> reference,
170	            IReadOnlyList<ModEntryModel> current,
171	            List<(int refIndex, int curIndex)> lcs)
172	        {
173	            // --- Step 0: Build fast lookup sets ---
174	            var lcsRefIndices = new HashSet<int>();
175	            var lcsCurIndices = new HashSet<int>();
176	            foreach (var (ri, ci) in lcs)
177	            {
178	                lcsRefIndices.Add(ri);
179	                lcsCurIndices.Add(ci);
180	            }
181	
182	            // Items in reference not in LCS → Removed candidates
183	            var removedMods = new List<ModEntryModel>();
184	            for (int i = 0; i < reference.Count; i++)
185	            {
186	                if (!lcsRefIndices.Contains(i))
187	                {
188	                    removedMods.Add(reference[i]);
189	                }
190	            }
191	
192	            // Items in current not in LCS → New candidates
193	            var newMods = new List<ModEntryModel>();
194	            for (int j = 0; j < current.Count; j++)
195	            {
196	                if (!lcsCurIndices.Contains(j))
197	                {
198	                    newMods.Add(current[j]);
199	                }
200	            }
201	
202	            // --- Step 1: LCS-shifted items (same relative order, different absolute position) ---
203	            // These are the "moved due to neighbour insertion/deletion" entries that will become
204	            // dependent changes. We track them but don't emit them as top-level entries yet.
205	            var lcsShifted = new List<(ModEntryModel mod, int refPos, int curPos)>();
206	            foreach (var (ri, ci) in lcs)
207	            {
208	                int refPos = reference[ri].LineNumber ?? (ri + 1);
209	                int curPos = current[ci].LineNumber ?? (ci + 1);
210	                if (refPos != curPos)
211	                {
212	                    lcsShifted.Add((reference[ri], refPos, curPos));
213	                }
214	            }
215	
216	            // --- Step 2: Same-filename reconciliation (Moved / swapped) ---
217	            var newByFilename = new Dictionary<string, ModEntryModel>(StringComparer.OrdinalIgnoreCase);
218	            foreach (var m in newMods)
219	            {
220	                newByFilename.TryAdd(m.FileName, m);
221	            }
222	
223	            var movedResults = new List<DiffLineModel>();
224	            var reconciledRemovedFilenames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
225	            // ReferenceEqualityComparer.Instance is intentional: ModEntryModel.Equals() compares by
226	            // FileName, so the default comparer would incorrectly de-duplicate two distinct instances
227	            // with the same filename. Identity comparison ensures we track the exact objects matched.
228	            var reconciledNewMods = new HashSet<ModEntryModel>(ReferenceEqualityComparer.Instance);
229	
230	            foreach (var removed in removedMods)
231	            {
232	                if (newByFilename.TryGetValue(removed.FileName, out var matchingNew))
233	                {
234	                    // Same filename appeared in both removed and new → swapped/moved
235	                    string text = _localization.GetString("DiffDialog", "MovedText_Description",
236	                        removed.FileName,
237	                        removed.LineNumber ?? 0,
238	                        matchingNew.LineNumber ?? 0);
239	                    movedResults.Add(new DiffLineModel(
240	                        removed.FileName, text, DiffChangeType.Moved,
241	                        removed.LineNumber, matchingNew.LineNumber));
242	
243	                    reconciledRemovedFilenames.Add(removed.FileName);
244	                    reconciledNewMods.Add(matchingNew);
245	                }
246	            }
247	
248	            // Remove reconciled items from working sets
249	            var remainingRemoved = removedMods
250	                .Where(m => !reconciledRemovedFilenames.Contains(m.FileName))

251	                .ToList();
252	            var remainingNew = newMods
253	                .Where(m => !reconciledNewMods.Contains(m))
254	                .ToList();
255	
256	            // --- Step 3: Replacement detection (LCS-aligned position matching) ---
257	            // Build a map from current-list positions of new items for quick lookup
258	            var newByCurPos = new Dictionary<int, ModEntryModel>();
259	            foreach (var m in remainingNew)
260	            {
261	                int pos = m.LineNumber ?? 0;
262	                // pos == 0 means LineNumber was null (no position assigned); skip — these entries
263	                // cannot participate in replacement matching and will be classified as Added.
264	                if (pos > 0 && !newByCurPos.ContainsKey(pos))
265	                {
266	                    newByCurPos[pos] = m;
267	                }
268	            }
269	
270	            // For each removed mod, determine its aligned current position.
271	            // The expected current position of a removed mod at reference position R is:
272	            //   R − (number of other removed mods at reference positions < R)
273	            // because each earlier deletion shifts the surviving items up by one slot.
274	
275	            // ReferenceEqualityComparer.Instance: same rationale as reconciledNewMods above —
276	            // we need object identity to avoid conflating two distinct ModEntryModel instances
277	            // that happen to share the same filename.
278	            var replacements = new Dictionary<ModEntryModel, ModEntryModel>(ReferenceEqualityComparer.Instance);
279	            var usedForReplacement = new HashSet<ModEntryModel>(ReferenceEqualityComparer.Instance);
280	
281	            // Sort removed mods by reference position for sequential processing
282	            var removedByRefPos = remainingRemoved
283	                .OrderBy(m => m.LineNumber ?? 0)
284	                .ToList();
285	
286	            int cumulativeDeletions = 0;
287	            foreach (var removed in removedByRefPos)
288	            {
289	                int refPos = removed.LineNumber ?? 0;
290	                // Aligned current position = reference position offset by the number of true
291	                // deletions that occurred before this position. Replacements do not shift
292	                // subsequent positions, so we only count unmatched removals.
293	                int alignedCurPos = refPos - cumulativeDeletions;
294	
295	                if (newByCurPos.TryGetValue(alignedCurPos, out var candidate)
296	                    && !usedForReplacement.Contains(candidate))
297	                {
298	                    replacements[removed] = candidate;
299	                    usedForReplacement.Add(candidate);
300	                    // A replacement is not a deletion: don't shift subsequent aligned positions.
301	                }
302	                else
303	                {
304	                    // True deletion — shifts subsequent positions by one.
305	                    cumulativeDeletions++;
306	                }
307	            }
308	
309	            // --- Step 4: Classify remaining new mods as Added or Inserted ---
310	            // maxSurvivingRefCurPos = highest current position of a mod that existed in reference
311	            // (either in LCS or as a moved/replacement pair)
312	            int maxSurvivingRefCurPos = 0;
313	            foreach (var (ri, ci) in lcs)
314	            {
315	                int curPos = current[ci].LineNumber ?? (ci + 1);
316	                if (curPos > maxSurvivingRefCurPos)
317	                    maxSurvivingRefCurPos = curPos;
318	            }
319	            // Also consider replacements: the replacement's current position counts as
320	            // "still within the reference range"
321	            foreach (var replacement in replacements.Values)
322	            {
323	                int curPos = replacement.LineNumber ?? 0;
324	                if (curPos > maxSurvivingRefCurPos)
325	                    maxSurvivingRefCurPos = curPos;
326	            }
327	
328	            // --- Step 5: Build the top-level result list ---
329	            var result = new List<DiffLineModel>();
330	
331	            // Replacement entries
332	            foreach (var removed in removedByRefPos)
333	            {
334	                if (replacements.TryGetValue(removed, out var replacement))
335	                {
336	                    int? lineNumber = removed.LineNumber ?? replacement.LineNumber;
337	                    string text = _localization.GetString("DiffDialog", "ReplacedText_Description",
338	                        removed.FileName, replacement.FileName, lineNumber ?? 0);
339	                    result.Add(new DiffLineModel(
340	                        removed.FileName, text, DiffChangeType.Replaced,
341	                        removed.LineNumber, replacement.LineNumber, replacement.FileName));
342	                }
343	                else
344	                {
345	                    // Truly removed
346	                    string text = _localization.GetString("DiffDialog", "RemovedText_Description",
347	                        removed.LineNumber ?? 0, removed.FileName);
348	                    result.Add(new DiffLineModel(
349	                        removed.FileName, text, DiffChangeType.Removed,
350	                        removed.LineNumber, null));
351	                }
352	            }
353	
354	            // Moved (swapped) entries
355	            result.AddRange(movedResults);
356	
357	            // Inserted / Added entries (new mods not used as replacements)
358	            foreach (var newMod in remainingNew)
359	            {
360	                if (usedForReplacement.Contains(newMod))
361	                    continue;
362	
363	                int curPos = newMod.LineNumber ?? 0;
364	                bool isInserted = curPos > 0 && curPos <= maxSurvivingRefCurPos;
365	                DiffChangeType changeType = isInserted ? DiffChangeType.Inserted : DiffChangeType.Added;
366	                string actionText = isInserted
367	                    ? _localization.GetString("DiffDialog", "InsertedText_Action")
368	                    : _localization.GetString("DiffDialog", "AddedText_Action");
369	                string text = _localization.GetString("DiffDialog", "ModChangeText_Description",
370	                    curPos, newMod.FileName, actionText);
371	                result.Add(new DiffLineModel(
372	                    newMod.FileName, text, changeType,
373	                    null, newMod.LineNumber));
374	            }
375	
376	            // LCS-shifted entries (dependent Moved)
377	            var shiftedLines = new List<DiffLineModel>();
378	            foreach (var (mod, refPos, curPos) in lcsShifted)
379	            {
380	                string text = _localization.GetString("DiffDialog", "MovedText_Description",
381	                    mod.FileName, refPos, curPos);
382	                shiftedLines.Add(new DiffLineModel(
383	                    mod.FileName, text, DiffChangeType.Moved,
384	                    refPos, curPos));
385	            }
386	
387	            // --- Step 6: Group shifted (dependent) lines under their causal change ---
388	            if (shiftedLines.Count > 0)
389	            {
390	                // Sort shifted lines by reference position for range-boundary processing
391	                var shiftedByRefPos = shiftedLines
392	                    .Where(s => s.ReferenceNumber.HasValue)
393	                    .OrderBy(s => s.ReferenceNumber!.Value)
394	                    .ToList();
395	
396	                var assignedShifted = new HashSet<DiffLineModel>(ReferenceEqualityComparer.Instance);
397	
398	                // --- 6a: Attribute to Removed entries using a range-based approach ---
399	                // Each removed mod "owns" the range from its reference position + 1 up to
400	                // (but not including) the next removal's reference position.  This mirrors
401	                // the original DetectAndAssignDependentChanges logic and ensures that
402	                // multiple consecutive removals each receive the correct subset of dependents.
403	                var removedEntries = result
404	                    .Where(r => r.ChangeType == DiffChangeType.Removed && r.ReferenceNumber.HasValue)
405	                    .OrderBy(r => r.ReferenceNumber!.Value)
406	                    .ToList();
407	
408	                for (int idx = 0; idx < removedEntries.Count; idx++)
409	                {
410	                    var removed = removedEntries[idx];
411	                    int startPos = removed.ReferenceNumber!.Value + 1;
412	
413	                    // Upper bound: the reference position of the next removal (exclusive).
414	                    int? stopBefore = (idx + 1 < removedEntries.Count)
415	                        ? removedEntries[idx + 1].ReferenceNumber
416	                        : (int?)null;
417	
418	                    foreach (var shifted in shiftedByRefPos)
419	                    {
420	                        if (assignedShifted.Contains(shifted))
421	                            continue;
422	
423	                        int refPos = shifted.ReferenceNumber!.Value;
424	                        if (refPos < startPos)
425	                            continue;
426	                        if (stopBefore.HasValue && refPos >= stopBefore.Value)
427	                            break;
428	
429	                        removed.DependentChanges.Add(shifted);
430	                        assignedShifted.Add(shifted);
431	                    }
432	                }
433	
434	                // --- 6b: Attribute remaining unassigned shifted mods to Inserted entries ---
435	                // An inserted mod at current position P shifts all surviving reference mods
436	                // at current positions >= P.
437	                var insertedEntries = result
438	                    .Where(r => r.ChangeType == DiffChangeType.Inserted && r.CurrentNumber.HasValue)
439	                    .OrderBy(r => r.CurrentNumber!.Value)
440	                    .ToList();
441	
442	                foreach (var inserted in insertedEntries)
443	                {
444	                    // The first unassigned shifted mod at or after the insertion's current position
445	                    var firstAffected = shiftedByRefPos
446	                        .Where(s => !assignedShifted.Contains(s) && s.CurrentNumber >= inserted.CurrentNumber)
447	                        .OrderBy(s => s.CurrentNumber)
448	                        .FirstOrDefault();
449	
450	                    if (firstAffected == null)

451	                        continue;
452	
453	                    int startRefPos = firstAffected.ReferenceNumber!.Value;
454	
455	                    // Next removal in reference space (to serve as upper boundary)
456	                    var nextRemoved = removedEntries
457	                        .Where(r => r.ReferenceNumber >= startRefPos)
458	                        .OrderBy(r => r.ReferenceNumber)
459	                        .FirstOrDefault();
460	
461	                    int? stopBefore = nextRemoved?.ReferenceNumber;
462	
463	                    foreach (var shifted in shiftedByRefPos)
464	                    {
465	                        if (assignedShifted.Contains(shifted))
466	                            continue;
467	
468	                        int refPos = shifted.ReferenceNumber!.Value;
469	                        if (refPos < startRefPos)
470	                            continue;
471	                        if (stopBefore.HasValue && refPos >= stopBefore.Value)
472	                            break;
473	
474	                        inserted.DependentChanges.Add(shifted);
475	                        assignedShifted.Add(shifted);
476	                    }
477	                }
478	
479	                // Add any unassigned shifted mods as top-level Moved entries
480	                foreach (var shifted in shiftedLines)
481	                {
482	                    if (!assignedShifted.Contains(shifted))
483	                    {
484	                        result.Add(shifted);
485	                    }
486	                }
487	            }
488	
489	            // Sort the top-level result in reference order (matching the old implementation's
490	            // ordering which iterated diffs sorted by ReferenceNumber then CurrentNumber).
491	            result.Sort((x, y) =>
492	            {
493	                int xKey = x.ReferenceNumber ?? int.MaxValue;
494	                int yKey = y.ReferenceNumber ?? int.MaxValue;
495	                if (xKey != yKey) return xKey.CompareTo(yKey);
496	                int xCur = x.CurrentNumber ?? int.MaxValue;
497	                int yCur = y.CurrentNumber ?? int.MaxValue;
498	                return xCur.CompareTo(yCur);
499	            });
500	
501	            return result;
502	        }
503	
504	    }
505	}

