 12	    {
 13	        private static readonly Encoding Utf8NoBom = new UTF8Encoding(false);
 14	
 15	        private static Dictionary<string, string> GetCaseLookup(string gamePath)
 16	        {
 17	            string dataPath = Path.Combine(gamePath, "Data");
 18	            if (!Directory.Exists(dataPath))
 19	            {
 20	                return new Dictionary<string, string>();
 21	            }
 22	
 23	            var files = Directory.EnumerateFiles(dataPath, "*.esm", SearchOption.AllDirectories)
 24	                .Concat(Directory.EnumerateFiles(dataPath, "*.esp", SearchOption.AllDirectories));
 25	
 26	            return files.ToDictionary(
 27	                p => Path.GetFileName(p).ToLowerInvariant(),
 28	                p => Path.GetFileName(p));
 29	        }
 30	
 31	        private static async Task<List<ModEntryModel>> ReadFileAsync(string filePath, bool isReferenceFile = false)
 32	        {
 33	            var result = new List<ModEntryModel>();
 34	            if (!File.Exists(filePath))
 35	            {
 36	                return result;
 37	            }
 38	
 39	            var lines = await File.ReadAllLinesAsync(filePath, Encoding.UTF8);
 40	            int logicalIndex = 0;
 41	            foreach (var line in lines)
 42	            {
 43	                if (!TryParseEnabledModEntry(line, out var entry))
 44	                {
 45	                    continue;
 46	                }
 47	
 48	                logicalIndex++;
 49	                entry.LineNumber = logicalIndex;
 50	                if (isReferenceFile)
 51	                {
 52	                    entry.OriginalLineNumber = logicalIndex;
 53	                }
 54	
 55	                result.Add(entry);
 56	            }
 57	
 58	            return result;
 59	        }
 60	
 61	        /// <summary>
 62	        /// Reads and parses an enabled-mod list from <paramref name="filePath"/>.
 63	        /// </summary>
 64	        /// <param name="filePath">Full path to the plugins or reference file.</param>
 65	        /// <param name="isReferenceFile">
 66	        /// When <see langword="true"/>, sets <see cref="ModEntryModel.OriginalLineNumber"/> on each
 67	        /// entry in addition to <see cref="ModEntryModel.LineNumber"/>.
 68	        /// </param>
 69	        /// <returns>A read-only list of enabled mod entries with sequential line numbers assigned.</returns>
 70	        public static async Task<IReadOnlyList<ModEntryModel>> ReadModListAsync(string filePath, bool isReferenceFile = false)
 71	        {
 72	            return await ReadFileAsync(filePath, isReferenceFile).ConfigureAwait(false);
 73	        }
 74	
 75	        public static bool DoesReferenceFileExist(AppConfigModel config)
 76	        {
 77	            return File.Exists(config.GetReferenceFilePath());
 78	        }
 79	
 80	        public static async Task CreateReferenceFileAsync(AppConfigModel config)
 81	        {
 82	            string targetPath = config.GetPluginsFilePath();
 83	            string referencePath = config.GetReferenceFilePath();
 84	
 85	            if (!File.Exists(targetPath))
 86	            {
 87	                throw new FileNotFoundException($"Target file not found: {targetPath}");
 88	            }
 89	
 90	            // Ensure the profile folder exists
 91	            var referenceDir = Path.GetDirectoryName(referencePath);
 92	            if (!string.IsNullOrEmpty(referenceDir) && !Directory.Exists(referenceDir))
 93	            {
 94	                Directory.CreateDirectory(referenceDir);
 95	            }
 96	
 97	            string content = await File.ReadAllTextAsync(targetPath, Encoding.UTF8);
 98	            await File.WriteAllTextAsync(referencePath, content, Utf8NoBom);
 99	        }
